import java.util.Scanner; public class Main { public static void main(String[] args) { Scanner sc = new Scanner(System.in); if (!sc.hasNextInt()) return; int n = sc.nextInt(); int k = sc.nextInt(); if (n == 1) { System.out.println(1); return; } long MOD = 1000000007; long[] dp = new long[n + 1]; dp[1] = 1; long currentSum = 1; for (int i = 2; i <= n; i++) { dp[i] = currentSum; currentSum = (currentSum + dp[i]) % MOD; if (i - k >= 1) { currentSum = (currentSum - dp[i - k] + MOD) % MOD; } } System.out.println(dp[n]); } }